INSERT INTO public.questionnaires (id,title,version,description,pass_percent,is_demo,is_active) VALUES ('41000000-0000-4000-8000-000000000001','Nautica da diporto · basi per la conduzione',1,'Preparazione dell’uscita, responsabilità al comando e sicurezza a bordo. Introduzione formativa, non corso abilitante né simulazione dell’esame ministeriale.',80,true,true);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000101','41000000-0000-4000-8000-000000000001',1,'Superare questo questionario consente di ottenere una patente nautica?','["No: la patente richiede il percorso ufficiale previsto per la categoria.","Sì, basta raggiungere l’80%.","Sì, se si naviga solo nel Mediterraneo."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000101',0);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000102','41000000-0000-4000-8000-000000000001',2,'Dove verificare quali requisiti servono per condurre una specifica unità in Italia?','["Nel risultato di un quiz generico online.","Nella normativa vigente e presso gli uffici competenti, considerando unità e navigazione prevista.","In base al solo nome commerciale della barca."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000102',1);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000103','41000000-0000-4000-8000-000000000001',3,'Come preparare il dispositivo individuale di galleggiamento prima di partire?','["Lasciarlo nella confezione per conservarlo.","Sceglierlo esclusivamente in base al colore.","Sceglierlo adatto alla persona, controllarlo e indossarlo correttamente."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000103',2);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000104','41000000-0000-4000-8000-000000000001',4,'Quale controllo richiede un giubbotto di salvataggio?','["Controlli e manutenzione secondo il fabbricante.","Nessun controllo se non è mai stato usato.","Solo una verifica del colore esterno."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000104',0);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000105','41000000-0000-4000-8000-000000000001',5,'Dove tenere un mezzo per chiedere aiuto?','["Sempre a terra per non danneggiarlo.","Protetto dall’acqua e raggiungibile.","Nel gavone più lontano dal posto di guida."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000105',1);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000106','41000000-0000-4000-8000-000000000001',6,'Quale informazione è essenziale per farsi localizzare in emergenza?','["Il prezzo pagato per la barca.","La marca degli occhiali da sole.","La propria posizione."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000106',2);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000107','41000000-0000-4000-8000-000000000001',7,'A cosa serve il dispositivo di arresto del motore con cordino, sulle unità che lo prevedono?','["Ad arrestare il motore se il conducente si allontana dalla postazione o cade fuori bordo.","Ad aumentare la potenza disponibile.","A sostituire il giubbotto di salvataggio."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000107',0);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000108','41000000-0000-4000-8000-000000000001',8,'Come usare il cordino di arresto del motore?','["Scollegarlo durante le manovre.","Verificarne il funzionamento e collegarlo al conducente secondo le istruzioni.","Legarlo a una parte fissa della barca per non perderlo."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000108',1);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000109','41000000-0000-4000-8000-000000000001',9,'Perché predisporre un’ancora adatta all’unità e al luogo?','["Garantisce l’ormeggio in qualsiasi fondale e condizione.","Sostituisce ogni mezzo di comunicazione.","Può aiutare a limitare la deriva in caso di perdita della propulsione, se utilizzabile in sicurezza."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000109',2);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000110','41000000-0000-4000-8000-000000000001',10,'Un aiuto al galleggiamento è necessariamente progettato per girare una persona incosciente a faccia in su?','["No, non va confuso con un dispositivo con quella funzione specifica.","Sì, qualunque modello ha questa funzione.","Sì, se è di colore acceso."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000110',0);
INSERT INTO public.questionnaires (id,title,version,description,pass_percent,is_demo,is_active) VALUES ('41000000-0000-4000-8000-000000000002','Kayak e SUP · uscire preparati',1,'Vento, attrezzatura, comunicazioni e pianificazione di un’uscita a pagaia. Le indicazioni generali vanno adattate al luogo e alle ordinanze locali.',80,true,true);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000201','41000000-0000-4000-8000-000000000002',1,'Quale vento è particolarmente insidioso per chi inizia a usare il SUP?','["Il vento da terra verso il largo.","Solo il vento che forma onde molto alte.","Nessun vento se la tavola è gonfiabile."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000201',0);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000202','41000000-0000-4000-8000-000000000002',2,'Una superficie calma vicino alla spiaggia garantisce un rientro facile con vento da terra?','["Sì, basta rimanere in piedi.","No, il vento può allontanare rapidamente la tavola.","Sì, l’assenza di onde elimina la deriva."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000202',1);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000203','41000000-0000-4000-8000-000000000002',3,'Come scegliere un aiuto al galleggiamento per pagaiare?','["Il più grande disponibile, senza regolarlo.","Solo in base al colore della tavola.","Adatto alla propria taglia e all’attività, indossato correttamente."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000203',2);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000204','41000000-0000-4000-8000-000000000002',4,'Come portare un telefono durante l’uscita?','["In custodia impermeabile e accessibile.","Non protetto sul fondo del kayak.","Lasciandolo sul pontile."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000204',0);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000205','41000000-0000-4000-8000-000000000002',5,'Un leash per SUP è adatto indistintamente a qualsiasi ambiente?','["Sì, purché il cavo sia il più lungo possibile.","No: tipo e sgancio devono essere appropriati all’ambiente e alla formazione ricevuta.","Sì, tutti i leash sono equivalenti."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000205',1);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000206','41000000-0000-4000-8000-000000000002',6,'Qual è un buon primo passo per iniziare il SUP?','["Provare da soli nel tratto più esposto.","Imparare soltanto quando si è già al largo.","Una lezione per apprendere tecnica, risalita e valutazione dell’ambiente."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000206',2);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000207','41000000-0000-4000-8000-000000000002',7,'Cosa valutare oltre al meteo prima di pagaiare?','["Correnti, temperatura dell’acqua e caratteristiche del luogo.","Soltanto la temperatura dell’aria.","Solo il numero di persone in spiaggia."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000207',0);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000208','41000000-0000-4000-8000-000000000002',8,'Come scegliere percorso e durata di un’uscita?','["Sempre fino al punto più lontano visibile.","In base alle capacità del gruppo e alle condizioni previste.","In base alla velocità del partecipante più esperto."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000208',1);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000209','41000000-0000-4000-8000-000000000002',9,'Perché comunicare a qualcuno a terra il programma dell’uscita?','["Per evitare di controllare le condizioni.","Per poter lasciare a terra ogni comunicazione.","Per rendere noto il percorso e quando è previsto il rientro."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000209',2);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000210','41000000-0000-4000-8000-000000000002',10,'Quali condizioni del vento considerare nella pianificazione?','["Intensità e direzione, attuali e previste.","Solo la direzione al momento della partenza.","Solo le condizioni della settimana precedente."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000210',0);
INSERT INTO public.questionnaires (id,title,version,description,pass_percent,is_demo,is_active) VALUES ('41000000-0000-4000-8000-000000000003','Snorkeling · esplorare in sicurezza',1,'Scelta del sito, compagno, attrezzatura e condizioni del mare per lo snorkeling in superficie. Non abilita all’apnea profonda o alle immersioni con autorespiratore.',80,true,true);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000301','41000000-0000-4000-8000-000000000003',1,'Quale organizzazione raccomanda BSAC per un’uscita di snorkeling?','["Una coppia in acqua e una persona di sorveglianza a terra.","Una persona sola, purché esperta.","Un gruppo senza accordi o sorveglianza."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000301',0);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000302','41000000-0000-4000-8000-000000000003',2,'Prima di entrare in acqua, cosa controllare?','["Niente se l’attrezzatura è nuova.","Maschera, boccaglio e pinne.","Solo la carica della fotocamera."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000302',1);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000303','41000000-0000-4000-8000-000000000003',3,'Un cinghiolo della pinna danneggiato va ignorato per una breve uscita?','["Sì, vicino alla costa non conta.","Sì, se la pinna ha un colore visibile.","No, occorre risolvere il difetto prima dell’uscita."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000303',2);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000304','41000000-0000-4000-8000-000000000003',4,'Quale sito è preferibile per iniziare?','["Un luogo riparato, adatto alle capacità e con accessi agevoli.","Un canale con intenso traffico di barche.","Una scogliera senza possibilità di uscita."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000304',0);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000305','41000000-0000-4000-8000-000000000003',5,'Perché individuare un’uscita alternativa dall’acqua?','["Per non dover controllare l’ingresso.","Per poter interrompere l’attività se necessario.","Per prolungare sempre la distanza percorsa."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000305',1);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000306','41000000-0000-4000-8000-000000000003',6,'Quale condizione rende un sito inadatto a un principiante?','["Un accesso comodo.","Una zona riparata adeguata al gruppo.","Correnti pericolose."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000306',2);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000307','41000000-0000-4000-8000-000000000003',7,'Quali informazioni consultare prima dell’uscita?','["Meteo e stato del mare.","Solo la temperatura prevista a mezzogiorno.","Solo le foto del luogo."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000307',0);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000308','41000000-0000-4000-8000-000000000003',8,'Come considerare maree e correnti locali nella pianificazione?','["Considerarle uguali in tutto il Mediterraneo.","Valutarle per il sito e l’orario scelti.","Ignorarle perché si resta in superficie."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000308',1);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000309','41000000-0000-4000-8000-000000000003',9,'Un quiz introduttivo basta per iniziare immersioni in apnea impegnative?','["Sì, se tutte le risposte sono corrette.","Sì, usando pinne più lunghe.","No, servono formazione specifica e preparazione adeguata."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000309',2);
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000310','41000000-0000-4000-8000-000000000003',10,'Qual è il modo appropriato per apprendere le tecniche di snorkeling?','["Seguire una formazione riconosciuta e progressiva.","Sperimentarle da soli lontano dalla riva.","Imitare video senza pratica assistita."]'::jsonb);
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000310',0);
